package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;

/**
 * Unit tests for TarUtils.formatUnsignedOctalString to maximize branch and line coverage.
 */
public class TarUtils_formatUnsignedOctalString_TriageGen1Test {

    @Test
    public void testValueZero() {
        byte[] buffer = new byte[8];
        TarUtils.formatUnsignedOctalString(0L, buffer, 0, 8);
        // Expected: padded with zeros "00000000"
        byte[] expected = "00000000".getBytes();
        assertArrayEquals(expected, buffer);
    }

    @Test
    public void testSmallValueWithPadding() {
        byte[] buffer = new byte[8];
        // Value 7 is octal 7. Length 8 -> "00000007"
        TarUtils.formatUnsignedOctalString(7L, buffer, 0, 8);
        byte[] expected = "00000007".getBytes();
        assertArrayEquals(expected, buffer);
    }

    @Test
    public void testExactFit() {
        byte[] buffer = new byte[3];
        // Value 17 is octal 21. Length 3 -> "021"
        TarUtils.formatUnsignedOctalString(17L, buffer, 0, 3);
        byte[] expected = "021".getBytes();
        assertArrayEquals(expected, buffer);
    }

    @Test
    public void testFullBuffer() {
        byte[] buffer = new byte[3];
        // Value 63 is octal 77. Length 3 -> "077"
        TarUtils.formatUnsignedOctalString(63L, buffer, 0, 3);
        byte[] expected = "077".getBytes();
        assertArrayEquals(expected, buffer);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOverflowThrowsException() {
        byte[] buffer = new byte[2];
        // Value 64 is octal 100. Length 2 is not enough.
        TarUtils.formatUnsignedOctalString(64L, buffer, 0, 2);
    }

    @Test
    public void testWithOffset() {
        byte[] buffer = new byte[10];
        // Fill buffer with dummy data
        for (int i = 0; i < 10; i++) {
            buffer[i] = (byte) 'X';
        }
        // Write "123" (octal) at offset 2 with length 3
        // octal 83 is 123
        TarUtils.formatUnsignedOctalString(83L, buffer, 2, 3);

        byte[] expected = {'X', 'X', '1', '2', '3', 'X', 'X', 'X', 'X', 'X'};
        assertArrayEquals(expected, buffer);
    }

    @Test
    public void testLargeValueExactFit() {
        // Max value for 8 octal digits is 8^8 - 1 = 16777215
        long value = 16777215L; 
        byte[] buffer = new byte[8];
        TarUtils.formatUnsignedOctalString(value, buffer, 0, 8);
        byte[] expected = "77777777".getBytes();
        assertArrayEquals(expected, buffer);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOverflowLargeValue() {
        byte[] buffer = new byte[1];
        TarUtils.formatUnsignedOctalString(8L, buffer, 0, 1);
    }
}
